// План specs/job-payments.md 1.1–1.3 (кейсы .qa/tests/job-payments/JP-01…JP-03). Pre-Prod, preprod-ttp (TTP Test Locks), десктоп, EN.
// @writes @data: в beforeAll создаётся работа «QA-AUTO pay … #67b4b4» с позицией $5 (остаток $5.00), в afterAll — Cancelled.
// Сами тесты ничего не сохраняют: окна закрываются без платежа. Serial — общая работа на три теста.
import { test, expect, BrowserContext, Page } from '@playwright/test';
import {
  REMAINING, WEB_METHODS, amountRe, blockMessaging, cancelJob, createJobWithBalance, methodButton, methodNames,
  openPaymentsTab, openRoleContext, openTakeAPayment, remainingCard,
} from './payments-helpers';

test.describe.configure({ mode: 'serial' });

test.describe('Job → Payments: вкладка и окно «Take a payment» (#67b4b4)', () => {
  let context: BrowserContext;
  let page: Page;
  let jobUrl: string | null = null;
  let messaging: string[] = [];

  test.beforeAll(async ({ browser }, testInfo) => {
    test.setTimeout(150_000);
    ({ context, page } = await openRoleContext(browser, testInfo));
    messaging = await blockMessaging(page);
    jobUrl = await createJobWithBalance(page, 'tab');
  });

  test.afterAll(async () => {
    await cancelJob(page, jobUrl);
    await context?.close();
  });

  test.afterEach(() => {
    expect(messaging, 'запросов отправки SMS/email быть не должно').toEqual([]);
  });

  test('QA-AUTO: Payments tab has no button row — Remaining to pay card, one summary, Payment history #67b4b4 @desktop @writes @data', async () => {
    await openPaymentsTab(page, jobUrl!);
    const main = page.getByRole('main');

    // Метка вкладки и карточка (источник: реджект п.1, решение 08.11)
    await expect(main.getByText(`Remaining to pay: ${REMAINING}`, { exact: true })).toBeVisible();
    const card = remainingCard(page);
    await expect(card).toBeVisible();
    await expect(card.getByText(amountRe(REMAINING))).toBeVisible();
    await expect(card.getByText('Take a payment', { exact: true })).toBeVisible();

    // Ряда кнопок способов во вкладке нет (комментарий 10.11 п.1)
    await expect(main.getByRole('button', { name: /^(Tap to Pay|Payment Link|Add Payment)$/ })).toHaveCount(0);

    // Одна сводка: Job Total $5.00, Amount Paid $0.00; двойной сводки нет
    await expect(main.getByText(/^Job Total:/)).toHaveCount(1);
    await expect(main.getByText(/^Amount Paid:/)).toHaveCount(1);
    await expect(main.getByText(/^Job Total:/).locator('..')).toContainText(REMAINING);
    await expect(main.getByText(/^Amount Paid:/).locator('..')).toContainText('$0.00');
    await expect(main.getByText(/^Outstanding/)).toHaveCount(0);

    await expect(main.getByText('Payment history', { exact: true })).toBeVisible();
  });

  test('QA-AUTO: Take a payment window — amount = remaining, pencil left of amount, web methods order without Tap to Pay #67b4b4 @desktop @writes @data', async () => {
    await openPaymentsTab(page, jobUrl!);
    const dialog = await openTakeAPayment(page);

    // Сумма = остаток (реджект п.3)
    await expect(dialog.getByText('Amount', { exact: true })).toBeVisible();
    const amount = dialog.getByText(amountRe(REMAINING)).first();
    await expect(amount).toBeVisible();

    // Карандаш «Change the amount» слева от суммы
    const pencil = dialog.getByRole('button', { name: 'Change the amount' });
    await expect(pencil).toBeVisible();
    const [p, a] = [await pencil.boundingBox(), await amount.boundingBox()];
    expect(p && a, 'координаты карандаша и суммы').toBeTruthy();
    expect(p!.x + p!.width, 'карандаш слева от суммы').toBeLessThanOrEqual(a!.x + 1);

    // Вопрос и порядок способов; Tap to Pay на вебе нет («מה רצוי» п.1; комментарий 10.11)
    await expect(dialog.getByText('How is the customer paying?', { exact: true })).toBeVisible();
    expect(await methodNames(dialog)).toEqual([...WEB_METHODS]);
    await expect(dialog.getByText(/Tap to Pay/i)).toHaveCount(0);

    // Карандаш → сумму можно изменить (поле с остатком)
    await pencil.click();
    const input = dialog.getByRole('spinbutton').or(dialog.getByRole('textbox')).first();
    await expect(input).toBeVisible();
    await expect(input).toBeEditable();
    await expect(input).toHaveValue(/^\$?5(\.00?)?$/);

    // Закрыть без платежа
    await page.keyboard.press('Escape');
    await expect(dialog).toBeHidden();
  });

  test('QA-AUTO: Cash in Take a payment opens Add Payment with type Cash and remaining amount #67b4b4 @desktop @writes @data', async () => {
    await openPaymentsTab(page, jobUrl!);
    const dialog = await openTakeAPayment(page);
    await methodButton(dialog, 'Cash').click();

    // Форма Add Payment: тип Cash, сумма = остаток (комментарий 10.11 п.1)
    const form = page.getByRole('dialog').filter({ hasText: /Add Payment/ });
    await expect(form).toBeVisible();
    await expect(form.getByRole('combobox').filter({ hasText: /^\s*Cash\s*$/ }).or(form.getByText('Cash', { exact: true })).first()).toBeVisible();
    await expect(form.getByLabel(/Amount/i).or(form.getByRole('spinbutton')).first()).toHaveValue(/^\$?5(\.00?)?$/);

    // Закрыть без сохранения → платёж не добавлен
    const cancel = form.getByRole('button', { name: /^Cancel$/ });
    if (await cancel.count()) await cancel.click();
    else await page.keyboard.press('Escape');
    await expect(form).toBeHidden();
    await page.reload();
    await expect(page.getByRole('main').getByText(`Remaining to pay: ${REMAINING}`, { exact: true })).toBeVisible();
  });
});
